use glam::{DMat4,DVec3};
use ingetrazo_core::{scene::SelectionItem,groups::Group,math::Ray,mesh::Mesh};
use ingetrazo_gui::IngeTrazoApp;
use ingetrazo_tools::base::{ToolContext,ToolType};
use serde_json::{Value,json};
fn load(case:&Value)->Mesh{let mut m=Mesh::new();for face in case["source"].as_array().unwrap(){let mut ring=|v:&Value|v.as_array().unwrap().iter().map(|p|m.add_vertex(DVec3::new(p[0].as_f64().unwrap(),p[1].as_f64().unwrap(),p[2].as_f64().unwrap()))).collect::<Vec<_>>();let outer=ring(&face["vertices"]);let holes=face["holes"].as_array().unwrap().iter().map(&mut ring).collect();let f=m.add_face(outer,holes).unwrap();m.faces[f].attrs=serde_json::from_value(face["attrs"].clone()).unwrap();}m}
fn center(m:&Mesh,f:usize)->DVec3{m.faces[f].vertices.iter().map(|&v|m.vertices[v].position).sum::<DVec3>()/m.faces[f].vertices.len()as f64}
fn grab(app:&mut IngeTrazoApp,f:usize)->ToolContext{let point=center(&app.scene.mesh,f);let normal=app.scene.mesh.face_normal(f);let ctx=ToolContext::new(point,Ray::new(point+normal*10.,-normal));app.set_tool(ToolType::PushPull);app.dispatch_tool_click(&ctx);ctx}
fn main(){let args:Vec<_>=std::env::args().collect();let input:Value=serde_json::from_slice(&std::fs::read(&args[1]).unwrap()).unwrap();let case=input["cases"].as_array().unwrap().iter().find(|c|c["name"]=="gable-extend").unwrap();let mesh=load(case);let f=case["face"].as_u64().unwrap()as usize;let mut rows=vec![];
 // A truly closed placement cannot be pushed by the outside tool.
 let mut outside=IngeTrazoApp::new();outside.scene.groups.push(Group::with_mesh("closed",mesh.clone()));let original=outside.scene.clone();let p=center(&mesh,f);let n=mesh.face_normal(f);let ctx=ToolContext::new(p,Ray::new(p+n*10.,-n));outside.set_tool(ToolType::PushPull);outside.dispatch_tool_click(&ctx);assert!(outside.status_message.contains("double-click"));assert!(outside.dispatch_tool_vcb("1m").is_err());assert_eq!(outside.scene,original);assert!(outside.undo_stack.is_empty());rows.push(json!({"case":"outside-closed-placement","atomic":true}));
 let mut app=IngeTrazoApp::new();let mut leaf=Group::with_mesh("shared",mesh.clone());leaf.transform=DMat4::from_translation(DVec3::new(2.,0.,0.));let leafid=leaf.id;app.scene.groups.push(leaf);app.scene.make_component(leafid).unwrap();let copy=app.scene.groups[0].duplicate_instance();let selected=app.scene.groups.remove(0);let mut parent=Group::new("parent");parent.transform=DMat4::from_rotation_z(std::f64::consts::FRAC_PI_2)*DMat4::from_translation(DVec3::new(4.,5.,6.));parent.children.push(selected);app.scene.groups.extend([parent,copy]);app.scene.select(SelectionItem::Group(0));app.begin_component_edit();app.scene.select(SelectionItem::Group(0));app.begin_component_edit();assert_eq!(app.component_edit_stack.len(),2);let before=app.scene.mesh.clone();let ctx=grab(&mut app,f);let normal=app.scene.mesh.face_normal(f);let mut moving=ctx.clone();moving.world+=normal*0.7;app.dispatch_tool_move(&moving);assert_eq!(app.scene.mesh,before);assert!(app.undo_stack.is_empty());app.active_tool.on_cancel(&mut app.scene);assert_eq!(app.scene.mesh,before);assert!(app.undo_stack.is_empty());rows.push(json!({"case":"nested-preview-cancel","depth":2,"undo":0,"mesh_exact":true}));
 grab(&mut app,f);assert!(app.dispatch_tool_vcb("NaN").is_err());assert_eq!(app.scene.mesh,before);assert!(app.undo_stack.is_empty());app.dispatch_tool_vcb("1000mm").unwrap();assert_eq!(app.undo_stack.len(),1);let after=app.scene.mesh.clone();
 app.undo();assert_eq!(app.scene.mesh,before);let mut control=grab(&mut app,f);control.ctrl_held=true;app.dispatch_tool_move(&control);control.ctrl_held=false;app.dispatch_tool_move(&control);app.dispatch_tool_vcb("1000mm").unwrap();assert_eq!(app.scene.mesh,after);assert_eq!(app.undo_stack.len(),1);rows.push(json!({"case":"nested-ctrl-release","same_as_normal":true,"undo":1}));
 app.undo();assert_eq!(app.scene.mesh,before);app.redo();assert_eq!(app.scene.mesh,after);app.finish_component_edit();app.finish_component_edit();assert_eq!(app.undo_stack.len(),1);assert_eq!(app.scene.groups[0].children[0].mesh,app.scene.groups[1].mesh);let local_after=app.scene.groups[1].mesh.clone();assert_ne!(local_after,mesh);app.undo();assert_eq!(app.scene.groups[1].mesh,mesh);app.redo();assert_eq!(app.scene.groups[1].mesh,local_after);rows.push(json!({"case":"nested-shared-finish-history","undo":1,"linked_meshes_exact":true,"preview_inert":true,"invalid_vcb_atomic":true,"unit_suffix":"1000mm"}));
 std::fs::write(&args[2],serde_json::to_vec_pretty(&json!({"passed":true,"cases":rows,"scope":"Real IngeTrazoApp transactional pointer-context/VCB handlers and component Finish/Undo/Redo; no rendered gesture claim"})).unwrap()).unwrap();}
